  'apps.games.title': 'Jeux',
  'apps.games.desc': 'Jeux P2P hors ligne : Poker, Blackjack, Rami, Défi Math. Jouez via Bluetooth avec les appareils proches. Résultats signés NOSTR empêchent la triche.',
  'apps.forum.title': 'Forum',
  'apps.forum.desc': 'Discussions en fils organisées par sections et sujets. Archives persistantes et consultables du savoir communautaire avec citations et pièces jointes.',
  'apps.market.title': 'Marché',
  'apps.market.desc': 'Commerce décentralisé avec boutiques, inventaire, commandes et avis vérifiés. Transactions pair-à-pair sans processeurs de paiement.',
  'apps.postcards.title': 'Cartes Postales',
  'apps.postcards.desc': 'Livraison de messages par chaînes de porteurs physiques. Les messages voyagent via des porteurs qui les tamponnent avec une preuve cryptographique.',
